  component vsync is
  port (
    A : in std_logic;
    B : out std_logic
    );
  end component vsync;

  signal resetn_2x : std_logic;
  signal resetn_cnn : std_logic;
begin

  --Ensure that the 2x clock constraints aren't optimized away
  process (clk_2x) is
  begin
    if rising_edge(clk_2x) then
      resetn_2x <= resetn;
    end if;
  end process;

  process (clk_cnn) is
  begin
    if rising_edge(clk_cnn) then
      resetn_cnn <= resetn;
    end if;
  end process;

  -- Ensure that verilog file are included
  vsync_i : component vsync
  port map (
    A  => '0',
    B  => open
  );

